"""Export the demo tariff snapshot from the backend's authoritative YAML configuration.

Run from the repository root: python -m scripts.export_valuation_demo
"""

import json
from pathlib import Path

from agents.valuation.config import valuation_config


def main() -> None:
    config = valuation_config().model_dump(mode="json")
    target = Path(__file__).resolve().parents[1] / "front/js/valuation-demo-config.js"
    target.write_text(
        "// Generated by python -m scripts.export_valuation_demo; edit configs/valuation.yaml.\n"
        + "// prettier-ignore\n"
        + "export default "
        + json.dumps(config, ensure_ascii=False, indent=2)
        + ";\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
